def roman_to_int(s):
    if not s or any(c not in 'IVXLCDM' for c in s):
        return None

    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    result = 0

    for i in range(len(s) - 1, -1, -1):
        current_value = values[s[i]]

        if i < len(s) - 1 and values[s[i + 1]] > current_value:
            result -= current_value
        else:
            result += current_value

    return result
```

