def title_case(s):
    if not s:
        return ""

    words = s.split()
    capitalized_words = []

    for word in words:
        if word.lower() in ["a", "l", "le", "et", "du", "des"]:
            capitalized_words.append(word)
        else:
            capitalized_words.append(word.capitalize())

    return " ".join(capitalized_words)
